/* Issue #156 native harness: the oracle's own libneatogen.a, called on
 * synthetic inputs read from stdin. One JSON object on stdout; doubles are
 * printed with %.17g, which round-trips a double exactly (non-finite values as
 * JSON strings).
 *
 * Modes (argv[1]):
 *   cgd    n maxit ortho1 tol, then A (n*n), x (n), b (n).
 *          Calls the archive's conjugate_gradient_d once per k = 1..maxit on
 *          fresh copies (the x after every iteration, with no instrumentation
 *          in the callee), then the traced copy (cgd_traced.c, generated by
 *          build.sh from the same conjgrad.c) for r.r, p.Ap and alpha.
 *   imds   n tol, graph rows, given coords (n). Calls compute_apsp (for the
 *          fixture's D) and IMDS_given_dim.
 *   hier   n dim opts model maxi levelsGap epsilon seed, graph rows. Calls
 *          stress_majorization_with_hierarchy after srand(1), srand48(seed).
 *
 * Graph rows: `hasW hasD`, then per vertex `nedges`, the edges, the ewgts when
 * hasW, the edists when hasD (neatoinit.c:makeGraphData's layout: one block
 * each for the whole graph).
 *
 * Built against 16.1.0 (-DHARNESS_NO_CGD, no conjugate_gradient_d there) the
 * imds and hier modes reproduce the fixtures the port carried before #156,
 * which is the check that the inputs are built as the earlier harnesses did.
 */
#include "config.h"
#include <cgraph/cgraph.h>
#include <common/globals.h>
#include <common/types.h>
#include <math.h>
#include <neatogen/conjgrad.h>
#include <neatogen/digcola.h>
#include <neatogen/kkutils.h>
#include <neatogen/neato.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TRACE 4096
static double traceVals[3][MAX_TRACE];
static int traceCount[3];

/* Called by the traced copy: kind 0 = r.r (initial, then each r_r_new),
 * 1 = p.Ap, 2 = alpha. */
__attribute__((noinline)) void h_trace(int kind, double v);
void h_trace(int kind, double v) {
  if (traceCount[kind] < MAX_TRACE) traceVals[kind][traceCount[kind]++] = v;
}

#ifndef HARNESS_NO_CGD
int h_conjugate_gradient_d(double **, double *, double *, int, double, int, bool);
#endif

static void pd(double v) {
  if (isnan(v)) printf("\"NaN\"");
  else if (isinf(v)) printf(v > 0 ? "\"Infinity\"" : "\"-Infinity\"");
  else printf("%.17g", v);
}

static void pvec(const char *key, const double *v, int n) {
  printf("\"%s\":[", key);
  for (int i = 0; i < n; i++) {
    if (i) printf(",");
    pd(v[i]);
  }
  printf("]");
}

static double rd(void) {
  double v;
  if (scanf("%lf", &v) != 1) {
    fprintf(stderr, "harness: short input\n");
    exit(2);
  }
  return v;
}

static int ri(void) { return (int)rd(); }

/* One block each for edges, ewgts and edists, as makeGraphData allocates
 * them: compute_y_coords restores ewgts by walking the first row's block. */
#define MAX_ENTRIES 65536
static vtx_data *readGraph(int n) {
  const int hasW = ri(), hasD = ri();
  vtx_data *graph = calloc((size_t)n, sizeof(vtx_data));
  int *edges = calloc(MAX_ENTRIES, sizeof(int));
  float *ewgts = hasW ? calloc(MAX_ENTRIES, sizeof(float)) : NULL;
  int8_t *edists = hasD ? calloc(MAX_ENTRIES, sizeof(int8_t)) : NULL;
  int used = 0;
  for (int i = 0; i < n; i++) {
    const int ne = ri();
    if (used + ne > MAX_ENTRIES) {
      fprintf(stderr, "harness: graph too large\n");
      exit(2);
    }
    graph[i].nedges = (size_t)ne;
    graph[i].edges = edges + used;
    for (int e = 0; e < ne; e++) graph[i].edges[e] = ri();
    if (hasW) {
      graph[i].ewgts = ewgts + used;
      for (int e = 0; e < ne; e++) graph[i].ewgts[e] = (float)rd();
    }
    if (hasD) {
      graph[i].edists = edists + used;
      for (int e = 0; e < ne; e++) graph[i].edists[e] = (int8_t)ri();
    }
    used += ne;
  }
  return graph;
}

#ifndef HARNESS_NO_CGD
static int modeCgd(void) {
  const int n = ri(), maxit = ri(), ortho1 = ri();
  const double tol = rd();
  double **A = calloc((size_t)n, sizeof(double *));
  double *storage = calloc((size_t)n * (size_t)n, sizeof(double));
  for (int i = 0; i < n; i++) {
    A[i] = storage + (size_t)i * (size_t)n;
    for (int j = 0; j < n; j++) A[i][j] = rd();
  }
  double *x0 = calloc((size_t)n, sizeof(double));
  double *b0 = calloc((size_t)n, sizeof(double));
  for (int i = 0; i < n; i++) x0[i] = rd();
  for (int i = 0; i < n; i++) b0[i] = rd();
  double *x = calloc((size_t)n, sizeof(double));
  double *b = calloc((size_t)n, sizeof(double));

  printf("{\"n\":%d,\"sweep\":[", n);
  for (int k = 1; k <= maxit; k++) {
    memcpy(x, x0, (size_t)n * sizeof(double));
    memcpy(b, b0, (size_t)n * sizeof(double));
    const int rv = conjugate_gradient_d(A, x, b, n, tol, k, ortho1 != 0);
    printf("%s{\"rv\":%d,", k > 1 ? "," : "", rv);
    pvec("x", x, n);
    printf("}");
  }
  memcpy(x, x0, (size_t)n * sizeof(double));
  memcpy(b, b0, (size_t)n * sizeof(double));
  const int rv = h_conjugate_gradient_d(A, x, b, n, tol, maxit, ortho1 != 0);
  printf("],\"traced\":{\"rv\":%d,", rv);
  pvec("x", x, n);
  printf(",");
  pvec("rr", traceVals[0], traceCount[0]);
  printf(",");
  pvec("pAp", traceVals[1], traceCount[1]);
  printf(",");
  pvec("alpha", traceVals[2], traceCount[2]);
  printf("}}\n");
  return 0;
}
#endif

static int modeImds(void) {
  const int n = ri();
  const double tol = rd();
  vtx_data *graph = readGraph(n);
  double *given = calloc((size_t)n, sizeof(double));
  double *out = calloc((size_t)n, sizeof(double));
  for (int i = 0; i < n; i++) given[i] = rd();

  DistType **D = compute_apsp(graph, n);
  printf("{\"n\":%d,\"D\":[", n);
  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++) printf("%s%d", i + j ? "," : "", D[i][j]);
  printf("],");
  const int rv = IMDS_given_dim(graph, n, given, out, tol);
  printf("\"rv\":%d,", rv);
  pvec("x", given, n);
  printf(",");
  pvec("y", out, n);
  printf("}\n");
  return 0;
}

static int modeHier(void) {
  const int n = ri(), dim = ri(), opts = ri(), model = ri(), maxi = ri();
  const double levelsGap = rd(), epsilon = rd();
  const long seed = (long)rd();
  vtx_data *graph = readGraph(n);

  /* Nodes without a position: initLayout draws drand48 for every one. */
  Agraph_t *g = agopen("h", Agdirected, NULL);
  node_t **nodes = calloc((size_t)n, sizeof(node_t *));
  for (int i = 0; i < n; i++) {
    char name[32];
    snprintf(name, sizeof name, "n%d", i);
    nodes[i] = agnode(g, name, 1);
  }
  aginit(g, AGNODE, "Agnodeinfo_t", sizeof(Agnodeinfo_t), true);

  double **coords = calloc((size_t)dim, sizeof(double *));
  for (int d = 0; d < dim; d++) coords[d] = calloc((size_t)n, sizeof(double));
  Epsilon = epsilon;
  srand(1);
  srand48(seed);
  const int rv = stress_majorization_with_hierarchy(graph, n, coords, nodes, dim,
                                                    opts, model, maxi, levelsGap);
  printf("{\"n\":%d,\"rv\":%d,\"coords\":[", n, rv);
  for (int d = 0; d < dim; d++) {
    printf("%s[", d ? "," : "");
    for (int i = 0; i < n; i++) {
      if (i) printf(",");
      pd(coords[d][i]);
    }
    printf("]");
  }
  printf("]}\n");
  return 0;
}

int main(int argc, char **argv) {
  if (argc < 2) return 2;
#ifndef HARNESS_NO_CGD
  if (strcmp(argv[1], "cgd") == 0) return modeCgd();
#endif
  if (strcmp(argv[1], "imds") == 0) return modeImds();
  if (strcmp(argv[1], "hier") == 0) return modeHier();
  return 2;
}
